const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const norwegianSea = ee.Geometry.Polygon([
    [[-5, 65], [10, 65], [10, 75], [-5, 75], [-5, 65]]
  ]);

  const date = '2019-06-05';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // 2. Data Acquisition - MODIS Aqua Ocean Color for chlorophyll-a
  let collection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(startDate, endDate)
    .filterBounds(norwegianSea);

  const collectionSize = collection.size().getInfo();
  console.log(`MODIS Aqua images on ${date}: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No MODIS Aqua data available for this date.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Get chlorophyll-a band
  const image = collection.first();
  const chlorophyll = image.select('chlor_a'); // Chlorophyll-a concentration

  // Check for valid pixels
  const pixelCount = chlorophyll.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: norwegianSea,
    scale: 1000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  console.log(`Valid chlorophyll pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid chlorophyll data after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get chlorophyll statistics
  const stats = chlorophyll.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.percentile([90]),
      sharedInputs: true
    }),
    geometry: norwegianSea,
    scale: 1000,
    maxPixels: 1e9
  });

  const meanChlor = stats.get('chlor_a_mean').getInfo();
  const p90Chlor = stats.get('chlor_a_p90').getInfo();

  console.log(`Mean chlorophyll: ${meanChlor ? meanChlor.toFixed(3) : 'null'} mg/m³`);
  console.log(`90th percentile: ${p90Chlor ? p90Chlor.toFixed(3) : 'null'} mg/m³`);

  // 5. Validation & Final Answer
  if (meanChlor === null || isNaN(meanChlor) || meanChlor < 0 || meanChlor > 30) {
    console.log("Invalid chlorophyll values detected.");
    console.log("<answer>C3</answer>");
  } else if (p90Chlor > 1.0) { // Using 90th percentile > 1 mg/m³ as bloom indicator
    console.log("Phytoplankton bloom detected (90th percentile > 1 mg/m³)");
    console.log("<answer>A</answer>");
  } else {
    console.log("No significant phytoplankton bloom detected");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
